<?php
declare(strict_types=1);
namespace TempNumber;
putenv('DB_DSN=sqlite::memory:');putenv('APP_ENV=testing');require __DIR__.'/../src/bootstrap.php';foreach(['Wallet','Pricing','Rewards','Payments']as$f)require_once __DIR__.'/../src/'.$f.'.php';foreach(glob(__DIR__.'/../migrations/*.sql')as$f)db()->exec(file_get_contents($f));
$passed=0;
function eq(mixed$a,mixed$b):void{if($a!==$b)throw new \RuntimeException(var_export($a,true).' !== '.var_export($b,true));}
function rejects(callable$f,string$code):void{try{$f();}catch(Problem$e){eq($e->key,$code);return;}throw new \RuntimeException('Expected '.$code);}
function test(string$name,callable$f):void{global$passed;foreach(['reward_claims','reward_costs','temp_mail_operations','fulfilment_intents','messages','ledger','payments','orders','inboxes','smm_orders','wallets','users']as$t)query('DELETE FROM '.$t);query("UPDATE settings SET value=? WHERE name='rewards_v3'",[json_encode(['enabled'=>true,'topup_launch_date'=>'2026-10-21'])]);$f();$passed++;echo "PASS $name\n";}
function customer(?array$ref=null):array{$id=id();query('INSERT INTO users (id,name,email,password_hash,referral_code,referred_by,created_at) VALUES (?,?,?,?,?,?,?)',[$id,'Rewards QA',$id.'@example.invalid','unused',strtoupper(substr(id(),0,10)),$ref['id']??null,now()]);query('INSERT INTO wallets (user_id,balance_cents) VALUES (?,1000000)',[$id]);return one('SELECT * FROM users WHERE id=?',[$id]);}
function charge(array$u,int$amount,string$reference,string$date):void{tx(fn()=>Wallet::change($u['id'],'purchase',-$amount,$reference,'Test purchase'));query('UPDATE ledger SET created_at=? WHERE reference=?',[$date,$reference]);}
function order(array$u,int$amount=2500,string$status='completed',string$product='usa',string$tier='retail',?string$date=null):string{
 $date=$date??now();$id=id();
 if(in_array($product,['usa','global'],true)){
 query('INSERT INTO orders (id,user_id,provider,product,service,status,price_cents,price_tier,idempotency_key,request_hash,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$u['id'],$product==='global'?'5sim':'textverified',$product,'QA',$status,$amount,$tier,id(),id(),$date,$date]);charge($u,$amount,'purchase:'.$id,$date);
 }elseif($product==='smm'){
 query('INSERT INTO smm_orders (id,user_id,service,target,quantity,status,price_cents,created_at) VALUES (?,?,?,?,?,?,?,?)',[$id,$u['id'],'QA','https://example.invalid',100,$status,$amount,$date]);commerce($u,$id,$amount,$product,$date);
 }elseif(in_array($product,['long-term','dedicated'],true)){
 query('INSERT INTO orders (id,user_id,provider,product,service,status,price_cents,price_tier,idempotency_key,request_hash,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$u['id'],'test',$product,'QA',$status,$amount,'retail',id(),id(),$date,$date]);commerce($u,$id,$amount,$product,$date);
 }elseif($product==='temp-mail'){
 query('INSERT INTO inboxes (id,user_id,provider_id,address,status,price_cents,created_at) VALUES (?,?,?,?,?,?,?)',[$id,$u['id'],id(),id().'@example.invalid',$status,$amount,$date]);$op=id();query('INSERT INTO temp_mail_operations (id,user_id,idempotency_key,operation,inbox_id,request_hash,price_cents,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)',[$op,$u['id'],id(),'create',$id,id(),$amount,$status==='pending'?'pending':'completed',$date,$date]);charge($u,$amount,'temp-mail-capture:'.$op,$date);
 }return$id;
}
function commerce(array$u,string$rid,int$amount,string$product,string$date):void{$op=id();query('INSERT INTO fulfilment_intents (id,user_id,product,operation,resource_id,request_hash,idempotency_key,price_cents,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[$op,$u['id'],$product,'purchase',$rid,id(),id(),$amount,'completed',$date,$date]);charge($u,$amount,'commerce-capture:'.$op,$date);}
function reward(array$u,string$id='monthly_spend',?\DateTimeImmutable$clock=null):array{foreach(Rewards::progress($u,$clock)['rewards']as$r)if($r['id']===$id)return$r;throw new \RuntimeException('Missing reward');}
function day(int$daysAgo):string{return(new \DateTimeImmutable('today',new \DateTimeZone('Europe/London')))->modify('-'.$daysAgo.' days')->setTime(12,0)->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s');}
function deposit(array$u,int$amount,string$date,string$status='successful',bool$captured=true):string{$id=id();query('INSERT INTO payments (id,user_id,provider,provider_reference,amount_cents,currency,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)',[$id,$u['id'],'stripe','cs_'.$id,$amount,'USD',$status,$date,$date]);if($captured){tx(fn()=>Wallet::change($u['id'],'topup',$amount,'topup:'.$id,'Verified deposit'));query('UPDATE ledger SET created_at=? WHERE reference=?',[$date,'topup:'.$id]);}return$id;}

test('Fresh accounts expose five rewards and unique registration links',function(){$u=customer();$p=Rewards::progress($u);eq(count($p['rewards']),5);eq($p['commercial_state'],'configured');eq(str_contains($p['referral_link'],$u['referral_code']),true);});
test('Monthly spend needs exactly USD 25 and pays USD 1 once',function(){$u=customer();order($u,2499);eq(reward($u)['eligible'],false);order($u,1);eq(reward($u)['eligible'],true);$b=Wallet::balance($u['id']);Rewards::claim($u,'monthly_spend');eq(cents(Wallet::balance($u['id'])['balance_usd']),cents($b['balance_usd'])+100);rejects(fn()=>Rewards::claim($u,'monthly_spend'),'REWARD_INELIGIBLE');eq(reward($u)['claimed'],true);});
test('Monthly progress excludes purchases in other London calendar months',function(){$u=customer();order($u,2500,'completed','usa','retail','2026-09-30 22:59:59');eq(reward($u,'monthly_spend',new \DateTimeImmutable('2026-10-15T12:00:00Z'))['progress'],0);order($u,2500,'completed','usa','retail','2026-09-30 23:00:00');eq(reward($u,'monthly_spend',new \DateTimeImmutable('2026-10-15T12:00:00Z'))['progress'],2500);});
test('London monthly periods handle summer winter and DST boundary',function(){[, $a,$b]=Rewards::period(new \DateTimeImmutable('2026-10-15T12:00:00Z'));eq($a,'2026-09-30 23:00:00');eq($b,'2026-11-01 00:00:00');[, $a]=Rewards::period(new \DateTimeImmutable('2026-12-15T12:00:00Z'));eq($a,'2026-12-01 00:00:00');});
test('Broad spending includes API partial Boost active long term dedicated and activated email',function(){$u=customer();order($u,500,'completed','usa','wholesale');order($u,500,'partial','smm');order($u,500,'active','long-term');order($u,500,'active','dedicated');order($u,500,'active','temp-mail');eq(reward($u)['progress'],2500);eq(reward($u,'cashback')['amount_usd'],'0.00');});
test('Failed cancelled pending refunded and uncaptured orders do not qualify',function(){$u=customer();foreach(['cancelled','pending','active','reconciliation','expired']as$s)order($u,2500,$s);order($u,2500,'cancelled','long-term');order($u,2500,'cancelled','smm');$id=order($u);tx(fn()=>Wallet::change($u['id'],'refund',2500,'refund:'.$id,'Refund'));$id=order($u);query('DELETE FROM ledger WHERE reference=?',['purchase:'.$id]);eq(reward($u)['progress'],0);});
test('A full seven day streak pays 50p and does not reuse rewarded days',function(){$u=customer();for($i=6;$i>=0;$i--)order($u,100,'completed','usa','retail',day($i));eq(reward($u,'streak')['eligible'],true);Rewards::claim($u,'streak');eq(reward($u,'streak')['progress'],0);rejects(fn()=>Rewards::claim($u,'streak'),'REWARD_INELIGIBLE');eq((int)one("SELECT SUM(amount_cents) AS n FROM reward_claims WHERE reward='streak'")['n'],50);});
test('Two non overlapping seven day blocks allow two separate streak rewards',function(){$u=customer();for($i=13;$i>=0;$i--)order($u,100,'completed','usa','retail',day($i));Rewards::claim($u,'streak');eq(reward($u,'streak')['eligible'],true);Rewards::claim($u,'streak');eq(reward($u,'streak')['eligible'],false);eq((int)one("SELECT SUM(amount_cents) AS n FROM reward_claims WHERE reward='streak'")['n'],100);});
test('Multiple orders in one day count once and a missing day resets streak',function(){$u=customer();for($i=0;$i<8;$i++)order($u,100,'completed','usa','retail',day(0));order($u,100,'completed','usa','retail',day(2));eq(reward($u,'streak')['progress'],1);});
test('Streak calendar days cross London DST without treating hours as days',function(){$u=customer();for($i=24;$i<=30;$i++)order($u,100,'completed','usa','retail',sprintf('2026-10-%02d 12:00:00',$i));eq(reward($u,'streak',new \DateTimeImmutable('2026-10-30T20:00:00Z'))['eligible'],true);});
test('Broader order categories can build a streak and old broken runs do not remain current',function(){$u=customer();foreach(['usa','global','smm','long-term','dedicated','temp-mail']as$i=>$p)order($u,100,$p==='smm'?'partial':(in_array($p,['long-term','dedicated','temp-mail'])?'active':'completed'),$p,'retail',day(5-$i));eq(reward($u,'streak')['progress'],6);});
test('Rental cashback pays exactly one percent and excludes API and other products',function(){$u=customer();order($u,2500);order($u,2500,'completed','global');order($u,10000,'completed','usa','wholesale');order($u,10000,'completed','smm');order($u,10000,'active','long-term');eq(reward($u,'cashback')['amount_usd'],'0.50');eq(reward($u,'cashback')['eligible'],true);Rewards::claim($u,'cashback');eq(reward($u,'cashback')['amount_usd'],'0.00');});
test('Cashback threshold is 50p and future incremental earnings survive a claim',function(){$u=customer();order($u,4999);eq(reward($u,'cashback')['amount_usd'],'0.49');eq(reward($u,'cashback')['eligible'],false);order($u,1);Rewards::claim($u,'cashback');order($u,6000);eq(reward($u,'cashback')['amount_usd'],'0.60');Rewards::claim($u,'cashback');eq(reward($u,'cashback')['claimed_usd'],'1.10');rejects(fn()=>Rewards::claim($u,'cashback'),'REWARD_INELIGIBLE');});
test('Fifty and one hundred US dollar deposits earn USD 2.50 and USD 5',function(){$u=customer();deposit($u,5000,now());eq(reward($u,'topup_bonus')['amount_usd'],'2.50');deposit($u,10000,now());eq(reward($u,'topup_bonus')['amount_usd'],'7.50');Rewards::claim($u,'topup_bonus');eq(reward($u,'topup_bonus')['amount_usd'],'0.00');});
test('Small deposits cannot combine and pending failed admin or reward credits do not qualify',function(){$u=customer();deposit($u,2500,now());deposit($u,2500,now());deposit($u,5000,now(),'pending');deposit($u,5000,now(),'failed');deposit($u,5000,now(),'successful',false);tx(fn()=>Wallet::change($u['id'],'bonus',10000,'fake-reward','Reward'));tx(fn()=>Wallet::change($u['id'],'adjustment',10000,'fake-admin','Admin credit'));eq(reward($u,'topup_bonus')['amount_usd'],'0.00');});
test('Programme launch uses London midnight and successful credit time',function(){$u=customer();deposit($u,5000,'2026-10-20 22:59:59');deposit($u,5000,'2026-10-20 23:00:00');eq(reward($u,'topup_bonus',new \DateTimeImmutable('2026-10-21T12:00:00Z'))['amount_usd'],'2.50');});
test('Verified top up callback retries cannot duplicate bonus earnings',function(){$u=customer();$id=id();query('INSERT INTO payments (id,user_id,provider,amount_cents,currency,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',[$id,$u['id'],'stripe',5000,'USD','pending',now(),now()]);$s=['id'=>'cs_'.$id,'metadata'=>['payment_id'=>$id,'user_id'=>$u['id']],'client_reference_id'=>$id,'currency'=>'usd','amount_total'=>5000,'payment_status'=>'paid'];Payments::credit($id,$s);Payments::credit($id,$s);eq(reward($u,'topup_bonus')['amount_usd'],'2.50');});
test('Referrals qualify on first order rather than registration or deposit',function(){$u=customer();$f=customer($u);deposit($f,5000,now());eq(Rewards::progress($u)['referrals']['qualified'],0);order($f,1,'partial','smm');eq(Rewards::progress($u)['referrals']['qualified'],1);order($f,100);eq(Rewards::progress($u)['referrals']['qualified'],1);});
test('Ten qualified referrals unlock both first milestones and one USD combined claim',function(){$u=customer();for($i=0;$i<10;$i++){ $f=customer($u);order($f,1); }eq(reward($u,'referral')['amount_usd'],'1.00');Rewards::claim($u,'referral');eq((int)one("SELECT COUNT(*) AS n FROM reward_claims WHERE reward='referral'")['n'],2);eq((int)one("SELECT COUNT(*) AS n FROM ledger WHERE user_id=? AND kind='bonus'",[$u['id']])['n'],1);rejects(fn()=>Rewards::claim($u,'referral'),'REWARD_INELIGIBLE');});
test('All referral milestones pay exactly USD 9.50 once with no reused milestone',function(){$u=customer();for($i=0;$i<50;$i++)order(customer($u),1);eq(reward($u,'referral')['amount_usd'],'9.50');Rewards::claim($u,'referral');eq(reward($u,'referral')['eligible'],false);eq((int)one("SELECT COUNT(*) AS n FROM reward_claims WHERE reward='referral'")['n'],4);});
test('First milestone can be collected separately before the next milestone',function(){$u=customer();for($i=0;$i<5;$i++)order(customer($u),1);Rewards::claim($u,'referral');for($i=0;$i<5;$i++)order(customer($u),1);eq(reward($u,'referral')['amount_usd'],'0.75');});
test('Self referrals and another customers wallet cannot create claims',function(){$u=customer();query('UPDATE users SET referred_by=? WHERE id=?',[$u['id'],$u['id']]);order($u);eq(Rewards::progress($u)['referrals']['qualified'],0);$v=customer();rejects(fn()=>Rewards::claim($v,'monthly_spend'),'REWARD_INELIGIBLE');});
test('Claim history records type amount period or milestone and timestamp',function(){$u=customer();order($u);Rewards::claim($u,'monthly_spend');$c=Rewards::progress($u)['claims'][0];eq($c['reward'],'monthly_spend');eq($c['amount_usd'],'1.00');eq($c['period'],Rewards::period()[0]);eq(str_ends_with($c['created_at'],'Z'),true);});
test('Paused and disabled accounts cannot claim',function(){$u=customer();order($u);query("UPDATE settings SET value=? WHERE name='rewards_v3'",[json_encode(['enabled'=>false,'topup_launch_date'=>'2026-10-21'])]);rejects(fn()=>Rewards::claim($u,'monthly_spend'),'REWARDS_UNCONFIGURED');query("UPDATE users SET status='disabled' WHERE id=?",[$u['id']]);rejects(fn()=>Rewards::claim($u,'monthly_spend'),'FORBIDDEN');});
test('A new London month resets progress and does not inherit the previous claim lock',function(){$u=customer();order($u);Rewards::claim($u,'monthly_spend');$clock=(new \DateTimeImmutable('now',new \DateTimeZone('Europe/London')))->modify('first day of next month');$r=reward($u,'monthly_spend',$clock);eq($r['progress'],0);eq($r['claimed'],false);});
test('Missing more than yesterday clears an incomplete historical streak',function(){$u=customer();for($i=5;$i>=2;$i--)order($u,100,'completed','usa','retail',day($i));eq(reward($u,'streak')['progress'],0);});
test('Top up bonus has no extra minimum even when only one penny is unclaimed',function(){$u=customer();deposit($u,5000,now());query('INSERT INTO reward_claims (id,user_id,reward,period,amount_cents,created_at) VALUES (?,?,?,?,?,?)',[id(),$u['id'],'topup_bonus','prior-bonus',249,now()]);eq(reward($u,'topup_bonus')['amount_usd'],'0.01');eq(reward($u,'topup_bonus')['eligible'],true);Rewards::claim($u,'topup_bonus');eq(reward($u,'topup_bonus')['amount_usd'],'0.00');});
test('Referral qualification includes the broader products even without cashback eligibility',function(){$u=customer();foreach(['long-term','dedicated','temp-mail','smm']as$p)order(customer($u),1,$p==='smm'?'partial':'active',$p);order(customer($u),1,'completed','usa','wholesale');eq(reward($u,'referral')['amount_usd'],'0.25');});
test('Late captured purchases use the spending month but preserve their order day for streaks',function(){$u=customer();$id=order($u,2500,'completed','usa','retail','2026-09-30 22:00:00');query('UPDATE ledger SET created_at=? WHERE reference=?',['2026-10-01 12:00:00','purchase:'.$id]);eq(reward($u,'monthly_spend',new \DateTimeImmutable('2026-10-15T12:00:00Z'))['progress'],2500);});
echo "$passed reward tests passed\n";
